import re

for note in ['MySQL-基础篇.md', 'MySQL-进阶篇.md', 'MySQL-运维篇.md']:
    with open(f'MySQL/{note}', encoding='utf-8') as f:
        lines = f.readlines()

    # Find patterns like "1   SELECT * FROM ..." (line number followed by SQL)
    bad_lines = []
    for i, line in enumerate(lines, 1):
        s = line.strip()
        # Pattern: starts with a number (1-3 digits), then whitespace, then SQL keyword
        if re.match(r'^\d{1,3}\s+(SELECT|INSERT|UPDATE|DELETE|CREATE|ALTER|DROP|SHOW|DESC|EXPLAIN|FROM|WHERE|VALUES|SET|GRANT|REVOKE|TRUNCATE|FLUSH|USE|LOAD|BEGIN|COMMIT|ROLLBACK)\b', s, re.I):
            bad_lines.append((i, s[:100]))
        # Pattern: standalone line number (just "1", "2", "3", etc.) followed by non-SQL text
        # These appear between code blocks as line number markers
        if re.match(r'^\d{1,3}\s{3,}', s) and len(s) < 80:
            bad_lines.append((i, s[:100]))

    if bad_lines:
        print(f'{note}: {len(bad_lines)} bad lines')
        for l in bad_lines[:10]:
            print(f'  L{l[0]}: {l[1]}')
        if len(bad_lines) > 10:
            print(f'  ... +{len(bad_lines)-10} more')
    else:
        print(f'{note}: clean')
    print()
