import re, os

def merge_table_rows(rows):
    """Merge |...| rows into a single markdown table."""
    if len(rows) == 1:
        return rows[0]

    parsed = []
    for r in rows:
        cells = [c.strip() for c in r.split('|')[1:-1]]
        parsed.append(cells)

    # Find max columns
    max_cells = max(len(r) for r in parsed)

    # Separate data rows from separator rows
    clean_rows = []
    for r in parsed:
        if all(c.strip() in ['---', '--- ', ' ---', ''] for c in r):
            continue  # skip separator, we'll create our own
        if any(c.strip() for c in r):
            clean_rows.append(r)

    if len(clean_rows) < 2:
        lines = ['| ' + ' | '.join(r) + ' |' for r in parsed]
        return '\n'.join(lines)

    # Ensure all rows have same column count
    for r in clean_rows:
        while len(r) < max_cells:
            r.append('')

    md = '| ' + ' | '.join(clean_rows[0]) + ' |\n'
    md += '| ' + ' | '.join(['---'] * max_cells) + ' |\n'
    for row in clean_rows[1:]:
        md += '| ' + ' | '.join(row) + ' |\n'
    return md.rstrip()


for note in ['MySQL-基础篇.md', 'MySQL-进阶篇.md', 'MySQL-运维篇.md']:
    fpath = os.path.join('MySQL', note)
    with open(fpath, encoding='utf-8') as f:
        lines = f.readlines()

    result = []
    table_buf = []
    for line in lines:
        s = line.strip()
        if re.match(r'^\|.+\|$', s):
            table_buf.append(s)
        else:
            if table_buf:
                merged = merge_table_rows(table_buf)
                result.append(merged)
                result.append('')
                table_buf = []
            result.append(line.rstrip('\n'))

    if table_buf:
        merged = merge_table_rows(table_buf)
        result.append(merged)
        result.append('')

    c = '\n'.join(result)
    c = re.sub(r'\n{4,}', '\n\n\n', c)

    with open(fpath, 'w', encoding='utf-8') as f:
        f.write(c)

    tables = len(re.findall(r'^\| ---', c, re.M))
    imgs = c.count('file:///D:/Java/data/MySQL/')
    missing = sum(1 for r in re.findall(r'file:///([^)\s]+)', c) if not os.path.exists(r.rstrip('"')))
    print(f'{note}: {tables} tables, {imgs} imgs, {missing} missing')

