import re

for note in ['MySQL-基础篇.md', 'MySQL-进阶篇.md', 'MySQL-运维篇.md']:
    with open(f'MySQL/{note}', encoding='utf-8') as f:
        c = f.read()

    # Show first 3 tables as they appear in the markdown
    lines = c.split('\n')
    in_table = False
    table_count = 0
    for i, line in enumerate(lines):
        if re.match(r'^\|.+\|$', line.strip()):
            if not in_table:
                table_count += 1
                if table_count <= 3:
                    print(f'{note} - table #{table_count}:')
                in_table = True
            if table_count <= 3:
                print(f'  {line.rstrip()[:130]}')
        else:
            if in_table and table_count <= 3:
                print()
            in_table = False
    print()
